import { Table, ReferenceColumn, GuidColumn, DomainIdColumn, DomainPathColumn } from '../../db'

export const kb_uc_can_read_mtom = Table({
    extends: 'sys_metadata',
    label: 'Who Can Read Knowledge Base',
    name: 'kb_uc_can_read_mtom',
    schema: {
        kb_knowledge_base: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Knowledge Base',
            mandatory: true,
            referenceTable: 'kb_knowledge_base',
        }),
        user_criteria: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Can Read',
            referenceTable: 'user_criteria',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: 'Domain',
        }),
        sys_domain_path: DomainPathColumn({
            default: '/',
            label: 'Domain Path',
            maxLength: 255,
        }),
        sys_id: GuidColumn({
            label: 'Sys ID',
            primary: true,
        }),
    },
})
